import numpy as np
import time
from numba import njit, prange
import scipy.linalg.blas as blas

@njit(parallel=True, fastmath=True)
def solve_numba_parallel(v1, v2):
    n1 = len(v1)
    n2 = len(v2)
    out = np.empty((n1, n2), dtype=v1.dtype)
    for i in prange(n1):
        for j in range(n2):
            out[i, j] = v1[i] * v2[j]
    return out

def solve_blas(v1, v2):
    # DGER for float64, SGER for float32
    if v1.dtype == np.float64:
        return blas.dger(1.0, v1, v2)
    elif v1.dtype == np.float32:
        return blas.sger(1.0, v1, v2)
    return np.outer(v1, v2)

def solve_np_outer(v1, v2):
    return np.outer(v1, v2)

v1 = np.random.rand(5000)
v2 = np.random.rand(5000)

for f in [solve_np_outer, solve_numba_parallel, solve_blas]:
    # warmup
    for _ in range(2): f(v1, v2)
    t0 = time.perf_counter()
    for _ in range(50): f(v1, v2)
    print(f"{f.__name__}: {time.perf_counter() - t0:.5f}")
